repo.visits.py:
"""Visit records."""


class Visit:
    def __init__(self, page, minutes):
        self.page = page
        self.minutes = minutes

    def __repr__(self):
        return "Visit(%r, %r)" % (self.page, self.minutes)


ROWS = [('docs', 35), ('docs', 58), ('home', 27), ('docs', 20), ('shop', 43)]


def load_visits():
    """Yield the stored visits one at a time."""
    for page, minutes in ROWS:
        yield Visit(page, minutes)

repo.labels.py:
"""Labels for visits."""


def label_visits(names, visits):
    """Return (lookup, lines): a name -> minutes dict and one 'name: minutes' line per visit."""
    pairs = zip(names, (x.minutes for x in visits))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)

