from visits import load_visits, ROWS
from labels import label_visits

NAMES = ["n%d" % i for i in range(len(ROWS))]


def test_lines_present():
    lookup, lines = label_visits(NAMES, load_visits())
    assert len(lines) == len(ROWS)


def test_line_text():
    lookup, lines = label_visits(NAMES, list(load_visits()))
    assert lines[0] == "n0: %s" % ROWS[0][1] and lines[-1] == "n%d: %s" % (len(ROWS) - 1, ROWS[-1][1])


def test_lookup_complete():
    lookup, lines = label_visits(NAMES, load_visits())
    assert lookup == {"n%d" % i: v for i, (_, v) in enumerate(ROWS)}


def test_no_names():
    assert label_visits([], load_visits()) == ({}, [])
